import{_ as t,o as a,c as r,ah as n}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Facturation","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/billing.md","filePath":"src/guide/billing.md"}'),s={name:"guide/billing.md"};function i(o,e,d,l,u,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="facturation" tabindex="-1">Facturation <a class="header-anchor" href="#facturation" aria-label="Permalink to &quot;Facturation&quot;">​</a></h1><p>Toute la facturation est en <strong>FCFA</strong>, hors taxe, stockée en <code>DECIMAL(12,2)</code>. Les factures portent une mention d&#39;exonération de TVA et les modalités de paiement réglées par l&#39;Administrateur. Elles sont générées en PDF, stockées de façon privée et envoyées par email au payeur.</p><h2 id="l-echeancier-30-40-30" tabindex="-1">L&#39;échéancier 30/40/30 <a class="header-anchor" href="#l-echeancier-30-40-30" aria-label="Permalink to &quot;L&#39;échéancier 30/40/30&quot;">​</a></h2><p>Chaque inscription produit <strong>trois factures</strong>, aux dates calculées par la cohorte :</p><table tabindex="0"><thead><tr><th>Tranche</th><th>Part</th><th>Échéance</th><th>Émission</th></tr></thead><tbody><tr><td>1</td><td>30 %</td><td>Début de la cohorte, ou signature si elle est postérieure</td><td>À la contre-signature de la convention</td></tr><tr><td>2</td><td>40 %</td><td>Mi-parcours</td><td>15 jours avant l&#39;échéance, avec le rappel J-15</td></tr><tr><td>3</td><td>30 %</td><td>Fin de la cohorte</td><td>15 jours avant l&#39;échéance, avec le rappel J-15</td></tr></tbody></table><p>Les dates ne sont jamais saisies : la date de mi-parcours et les trois échéances sont calculées à partir des dates de la cohorte. Les références sont annuelles et lisibles : <code>FAC-NB-AAAA-XXX</code> pour les factures, <code>AV-NB-AAAA-XXX</code> pour les avoirs.</p><h2 id="financement-partage" tabindex="-1">Financement partagé <a class="header-anchor" href="#financement-partage" aria-label="Permalink to &quot;Financement partagé&quot;">​</a></h2><p>Avant la signature, le Coordinateur désigne un <strong>financeur</strong> (compte organisation au rôle Financeur) et sa part, de 1 à 100 %. La répartition figure dans la convention.</p><ul><li>Chaque tranche est facturée en <strong>une facture par payeur</strong> : l&#39;apprenant et le financeur sont suivis séparément.</li><li>Le financeur voit, dans son espace, les apprenants qu&#39;il finance et les factures de sa part.</li><li>Si le financeur est en retard, l&#39;accès Sève de l&#39;apprenant est suspendu <strong>même si sa propre part est payée</strong>. Le paiement rétablit l&#39;accès.</li></ul><h2 id="encaissement" tabindex="-1">Encaissement <a class="header-anchor" href="#encaissement" aria-label="Permalink to &quot;Encaissement&quot;">​</a></h2><p>Les paiements sont saisis par le Coordinateur : montant, moyen, référence, date. Les paiements <strong>partiels</strong> sont possibles. Un accusé est envoyé au payeur.</p><table tabindex="0"><thead><tr><th>Moyen</th><th>Saisie</th></tr></thead><tbody><tr><td>Virement</td><td>Manuelle</td></tr><tr><td>Chèque</td><td>Manuelle</td></tr><tr><td>Mobile Money (Flooz, T-Money)</td><td>Manuelle</td></tr><tr><td>Carte bancaire</td><td>Manuelle</td></tr><tr><td>Espèces</td><td>Manuelle</td></tr></tbody></table><p>Le paiement en ligne <strong>PayGate</strong> (Flooz, T-Money) est prévu par l&#39;ADR-006 mais n&#39;est pas encore branché : tant qu&#39;il ne l&#39;est pas, tous les encaissements passent par la saisie manuelle.</p><h2 id="relances" tabindex="-1">Relances <a class="header-anchor" href="#relances" aria-label="Permalink to &quot;Relances&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Moment</th><th>Événement</th><th>Acteur</th></tr></thead><tbody><tr><td>J-15, J-7, J-1</td><td>Rappel d&#39;échéance (email, Sève, WhatsApp)</td><td>Kura</td></tr><tr><td>J+1</td><td>Rappel d&#39;échéance non réglée</td><td>Kura</td></tr><tr><td>J+7</td><td>Relance personnalisée (email ou appel)</td><td>Coordinateur pédagogique</td></tr><tr><td>J+15</td><td>Facture <strong>en retard</strong>, début du <strong>moratoire automatique</strong> de 15 jours</td><td>Kura</td></tr><tr><td>J+30</td><td>Sans paiement, <strong>suspension de l&#39;accès Sève</strong></td><td>Kura</td></tr><tr><td>Après J+30</td><td>Entretien, plan de régularisation, désinscription si rien</td><td>Coordinateur pédagogique</td></tr></tbody></table><p>Le moratoire est <strong>unique et non renégociable</strong> : il reporte l&#39;échéance de 15 jours et reste visible sur la facture. Le paiement, à toute étape, rétablit automatiquement l&#39;accès.</p><p>Cette chronologie remplace les règles antérieures (« en retard » à J+1, moratoire sur demande, suspension à J+15, échéance à 15 jours de l&#39;émission).</p><h2 id="avoirs-et-remboursements" tabindex="-1">Avoirs et remboursements <a class="header-anchor" href="#avoirs-et-remboursements" aria-label="Permalink to &quot;Avoirs et remboursements&quot;">​</a></h2><p>Un avoir <code>AV-NB-AAAA-XXX</code> porte un type :</p><ul><li><strong>annulation du reste dû</strong> : les tranches non encore réglées sont annulées ;</li><li><strong>remboursement</strong> : les sommes déjà payées sont restituées, une fois le remboursement effectué.</li></ul><p>Cas principaux :</p><table tabindex="0"><thead><tr><th>Cas</th><th>Traitement</th></tr></thead><tbody><tr><td>Changement de cohorte (report, force majeure)</td><td>Paiements conservés ; reste dû annulé par avoir ; nouvelle convention facturant chaque tranche déduction faite des paiements</td></tr><tr><td>Annulation de cohorte par NextBoxx</td><td>Avoir de remboursement de 100 % des sommes payées ; remboursement enregistré par le Coordinateur</td></tr><tr><td>Abandon volontaire</td><td>Aucun avoir ; tranches restantes non facturées ; factures émises restant dues ; attestation partielle</td></tr><tr><td>Annulation d&#39;un événement</td><td>Avoir pour les inscrits payés ; reste dû annulé</td></tr><tr><td>Inscription à un événement non payée à 48 h</td><td>Avoir du reste dû, place libérée</td></tr></tbody></table><h2 id="factures-hors-echeancier" tabindex="-1">Factures hors échéancier <a class="header-anchor" href="#factures-hors-echeancier" aria-label="Permalink to &quot;Factures hors échéancier&quot;">​</a></h2><p>Seuls ces événements facturent en dehors de l&#39;échéancier d&#39;une inscription :</p><ul><li>une demande de rattrapage ou de repêchage, facturée immédiatement ;</li><li>une inscription à un événement payant ;</li><li>un devis B2B accepté ;</li><li>une mise en relation ou un accompagnement confirmé.</li></ul><p>Toute autre facture est validée par le Coordinateur.</p><p>Les factures d&#39;événement n&#39;ont ni inscription de formation, ni convention, ni tranche. Elles sont échues 48 h avant le début de l&#39;événement et exclues du calendrier de facturation, des relances de formation, des commissions et des tableaux de bord.</p><h2 id="remunerations-et-commissions" tabindex="-1">Rémunérations et commissions <a class="header-anchor" href="#remunerations-et-commissions" aria-label="Permalink to &quot;Rémunérations et commissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bénéficiaire</th><th>Base de calcul</th><th>Versement</th></tr></thead><tbody><tr><td>Formateur Principal</td><td>Heures du référentiel × taux horaire de la zone, + forfait projet</td><td>Validé par le Coordinateur, versé hors Kura</td></tr><tr><td>Coach-Tuteur</td><td>Effectif au démarrage × forfait coach, partagé entre co-coachs</td><td>Idem</td></tr><tr><td>Jury externe</td><td>Jeton dû à la tenue effective de la soutenance</td><td>Idem</td></tr><tr><td>Apporteur d&#39;affaires</td><td>5 % de chaque paiement encaissé, part du financeur comprise</td><td>Idem ; ligne négative en cas de remboursement</td></tr><tr><td>Partenaire marketing</td><td>Facture déposée, dans la limite du contrat ou du forfait</td><td>Validée ou rejetée avec motif, puis versée</td></tr></tbody></table><p>Une cohorte garde les taux et la zone de son <strong>démarrage</strong>, même si un apprenant abandonne ensuite. Les montants calculés sont ajustables par le Coordinateur avant validation ; le versement est toujours enregistré après coup, car il a lieu hors de Kura.</p><h2 id="indicateurs-financiers" tabindex="-1">Indicateurs financiers <a class="header-anchor" href="#indicateurs-financiers" aria-label="Permalink to &quot;Indicateurs financiers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Indicateur</th><th>Définition</th></tr></thead><tbody><tr><td>Facturé</td><td>Somme des factures, nette des avoirs d&#39;annulation</td></tr><tr><td>Encaissé</td><td>Somme des paiements, nette des remboursements</td></tr><tr><td>Reste dû</td><td>Facturé − encaissé, dont la part en retard</td></tr><tr><td>Versé</td><td>Rémunérations et commissions versées, plus les factures marketing payées</td></tr><tr><td>Marge brute</td><td>Encaissé − versé</td></tr></tbody></table><p>La vue Direction ajoute le versé et la marge brute ; le reporting s&#39;arrête au reste dû. Les deux vues excluent les factures d&#39;événement.</p><h2 id="bonnes-pratiques" tabindex="-1">Bonnes pratiques <a class="header-anchor" href="#bonnes-pratiques" aria-label="Permalink to &quot;Bonnes pratiques&quot;">​</a></h2><ul><li>Enregistrer un paiement <strong>dans une transaction</strong> et vérifier le solde après verrouillage de la ligne, pour éviter un surpaiement en cas de saisies simultanées.</li><li>Ne jamais émettre une facture sans vérifier qu&#39;elle n&#39;existe pas déjà pour la même convention, le même payeur et la même tranche.</li><li>Conserver les PDF et leurs empreintes : une facture émise ne se réédite pas, elle se corrige par un avoir.</li></ul>',35)])])}const h=t(s,[["render",i]]);export{m as __pageData,h as default};
